<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue';const props=defineProps<{modelValue:number,count:number}>();const emit=defineEmits<{'update:modelValue':[value:number]}>();const playing=ref(false);const speed=ref(1);let timer:ReturnType<typeof setInterval>|undefined;
function stop(){playing.value=false;clearInterval(timer)}function seek(i:number){emit('update:modelValue',Math.max(0,Math.min(props.count-1,i)))}function toggle(){if(playing.value){stop();return}if(props.modelValue>=props.count-1)seek(0);playing.value=true;timer=setInterval(()=>{if(props.modelValue>=props.count-1)stop();else seek(props.modelValue+1)},1000/speed.value)}watch(speed,()=>{if(playing.value){stop();toggle()}});watch(()=>props.count,stop);onBeforeUnmount(stop);defineExpose({stop});
</script>
<template><div class="replay"><button @click="stop();seek(0)" title="重置">↺</button><button :disabled="!modelValue" @click="stop();seek(modelValue-1)">上一步</button><button class="primary" :disabled="count<2" @click="toggle">{{playing?'暂停':'▶ 播放'}}</button><button :disabled="modelValue>=count-1" @click="stop();seek(modelValue+1)">下一步</button><input type="range" :min="0" :max="Math.max(0,count-1)" :value="modelValue" aria-label="过程进度" @input="stop();seek(Number(($event.target as HTMLInputElement).value))"><span>{{count?modelValue+1:0}} / {{count}}</span><select v-model.number="speed" aria-label="播放速度"><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></div></template>
